window.html2pdf = function() {
    let elementToPrint = null;
    let fileOptions = {};
  
    return {
      set: function(opt) {
        fileOptions = opt;
        return this;
      },
      from: function(element) {
        elementToPrint = element;
        return this;
      },
      output: function(type) {
        return new Promise((resolve) => {
          if (type === 'blob') {
            const title = elementToPrint.querySelector('h1') ? elementToPrint.querySelector('h1').innerText : 'Документ';
            let htmlContent = `
              <!DOCTYPE html>
              <html>
              <head>
                <meta charset="utf-8">
                <title>${title}</title>
                <style>
                  body { font-family: 'Arial', sans-serif; padding: 40px; color: #333; background: #fff; }
                  h1 { color: #1e40af; border-bottom: 2px solid #1e40af; padding-bottom: 10px; margin-bottom: 20px; font-size: 24px; }
                  ol, ul { padding-left: 20px; line-height: 1.8; font-size: 16px; }
                  li { margin-bottom: 10px; }
                  table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                  td, th { border: 1px solid #cbd5e1; padding: 10px; text-align: center; font-size: 14px; }
                  th { background-color: #f8fafc; font-weight: bold; }
                </style>
              </head>
              <body>
                ${elementToPrint.innerHTML}
                <script>
                  window.onload = function() { window.print(); }
                <\/script>
              </body>
              </html>
            `;
            
            const blob = new Blob([htmlContent], { type: 'application/pdf' });
            resolve(blob);
          }
        });
      }
    };
  };
  